//! Native source gate, feedback, and trace export contract matrix.
//! Stateful HTTP repository authorization is not replaced by these pure contracts.
#[path="trace_feedback_source_matrix.rs"]mod trace_feedback_source_matrix;
use ai_platform_gateway::migration_compat::{eval_gate,eval_behavior,eval_export};
use serde_json::{Value,json};
fn case()->Value{json!({"case_id":"assistant.runtime.test","split":"regression","input":{"input_preview":"test"},"expected_output":{"contains":"ok"},"expected_trajectory":{"required_span_kinds":[],"runtime":{}},"assertions":[{"type":"output_contains","value":"ok"}],"metadata":{"critical":true}})}
fn replay()->Value{json!({"status":"succeeded","output_preview":"ok","span_kinds":[]})}
#[test]fn frozen_original_gate_receipts_match_exactly(){let cases:Vec<Value>=serde_json::from_str(include_str!("fixtures/runtime_gate_source.json")).unwrap();assert_eq!(cases.len(),11);for(i,c)in cases.iter().enumerate(){let o=&c["options"];let actual=eval_gate::apply_gate(&c["metrics"],o.get("thresholds"),o.get("baseline_metrics"),o["require_critical_coverage"].as_bool().unwrap_or(false),o["require_stateful_coverage"].as_bool().unwrap_or(false));assert_eq!(actual,c["expected"],"original gate receipt {i}");}}
#[test]fn unknown_assertion_and_missing_observation_fail_closed(){let mut c=case();c["assertions"]=json!([{"type":"unknown_rule"}]);assert!(!eval_behavior::validate_case(&c).is_empty());let r=eval_behavior::evaluate_case(&case(),None);assert_eq!(r["passed"],false);assert!(r["failures"].as_array().unwrap().contains(&json!("missing replay observation")));}
#[test]fn runtime_and_latency_mismatches_fail(){let mut c=case();c["assertions"]=json!([{"type":"latency_ms_lt","value":100}]);c["expected_trajectory"]["runtime"]=json!({"expected_exit_reason":"approval_denied","memory_sync":"skipped"});let mut r=replay();r["total_latency_ms"]=json!(101);r["exit_reason"]=json!("succeeded");r["memory_sync"]=json!("written");assert_eq!(eval_behavior::evaluate_case(&c,Some(&r))["passed"],false);}
#[test]fn failure_mode_absent_requires_explicit_evidence(){let mut c=case();c["assertions"]=json!([{"type":"failure_mode_absent","value":"tool_error"}]);for value in [replay(),json!({"status":"succeeded","output_preview":"ok","span_kinds":[],"failure_mode":""})]{let result=eval_behavior::evaluate_case(&c,Some(&value));assert_eq!(result["passed"],false);assert!(result["failures"].as_array().unwrap().contains(&json!("failure_mode_absent missing evidence")));}for evidence in [json!({"failure_modes":[]}),json!({"failure_modes":["latency_regression"]}),json!({"failure_mode":"latency_regression"})]{let mut r=replay();r.as_object_mut().unwrap().extend(evidence.as_object().unwrap().clone());assert_eq!(eval_behavior::evaluate_case(&c,Some(&r))["passed"],true);}}
#[test]fn external_observation_overrides_inline_replay(){let mut c=case();c["metadata"]["replay"]=replay();let external=json!({"status":"failed","output_preview":"not ok","span_kinds":[]});let r=eval_behavior::evaluate_case(&c,Some(&external));assert_eq!(r["passed"],false);assert!(r["failures"].as_array().unwrap().contains(&json!("status=failed")));}
#[test]fn sensitive_replay_is_a_failure(){let mut r=replay();r["output_preview"]=json!("ok Authorization: Bearer raw-token");let r=eval_behavior::evaluate_case(&case(),Some(&r));assert_eq!(r["passed"],false);assert!(r["failures"].as_array().unwrap().contains(&json!("sensitive replay payload")));}
#[test]fn trace_export_defensively_redacts_all_source_secret_locations(){let detail=json!({"trace":{"trace_id":"11111111-1111-4111-8111-111111111111","model_id":"qwen3.6-plus","total_tokens":30,"input_preview":"hello Authorization: Bearer raw-trace-token","output_preview":"safe","metadata":{"headers":{"Authorization":"Bearer raw-header-token","Cookie":"sid=raw-cookie"},"callback_url":"https://user:raw-password@example.test/path"}},"spans":[{"span_id":"span","span_kind":"tool_execution","name":"tool","status":"succeeded","attributes":{"api_key":"raw-api-key","note":"access_token=raw-access-token"}}],"events":[{"event_type":"tool_call","payload":{"headers":{"Authorization":"Bearer raw-event-token"},"cookie":"raw-event-cookie","body":"password=raw-password"}}],"scores":[]});let payload=eval_export::export_trace(&detail,"otel");let serialized=payload.to_string();for secret in ["raw-trace-token","raw-header-token","raw-event-token","raw-cookie","raw-event-cookie","raw-api-key","raw-access-token","raw-password"]{assert!(!serialized.contains(secret),"export leaked {secret}");}assert!(serialized.contains("[redacted]"));assert_eq!(payload["trace"]["attributes"]["gen_ai.request.model"],"qwen3.6-plus");assert_eq!(payload["trace"]["attributes"]["gen_ai.usage.total_tokens"],30);}
